"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15401"],{14291(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.periodo_inscricao_nao_informavel","status":422,"titulo":"O per\xedodo de inscri\xe7\xe3o vem da janela da fase do cronograma que coleta inscri\xe7\xe3o e n\xe3o pode ser informado na publica\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.periodo_inscricao_nao_informavel","requisitos":["UNI-REQ-0106"],"oQueAconteceu":["O ato informou um per\xedodo de inscri\xe7\xe3o, mas o cronograma do processo tem uma fase\\nque **coleta inscri\xe7\xe3o** \u2014 e \xe9 o per\xedodo dessa fase que define o prazo que o Edital\\npublica.","O per\xedodo existia em dois lugares e nada os conciliava: informado no ato e\\ndefinido no per\xedodo da fase. Um Edital podia declarar inscri\xe7\xf5es at\xe9 15 de abril\\nenquanto a fase de coleta fechava em 20 de mar\xe7o, e as duas vers\xf5es iam\\ncongeladas na mesma publica\xe7\xe3o, cada uma dizendo uma coisa.","A recusa existe para que a diverg\xeancia apare\xe7a. Aceitar o valor informado e\\ndescart\xe1-lo em sil\xeancio esconderia justamente o desencontro que o operador\\nprecisa ver."],"comoResolver":["Publique **sem informar** o per\xedodo. Ele \xe9 projetado do per\xedodo da fase que coleta\\ninscri\xe7\xe3o \u2014 a de menor ordem, quando h\xe1 mais de uma.","Se o prazo que voc\xea queria declarar \xe9 diferente do que est\xe1 no cronograma, \xe9 o\\ncronograma que precisa mudar. Com o processo j\xe1 publicado, isso passa por uma retifica\xe7\xe3o que corrija o per\xedodo da fase \u2014 o prazo do Edital acompanha.","Certame cujos candidatos v\xeam de importa\xe7\xe3o externa n\xe3o tem fase que colete\\ninscri\xe7\xe3o, e nele o per\xedodo **continua sendo informado** no ato: n\xe3o h\xe1 per\xedodo de\\nonde projet\xe1-lo, e n\xe3o h\xe1 diverg\xeancia poss\xedvel."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);